input.command:
$q = @'
mutation { updateProjectV2Field(input: { fieldId: "REDACTED", singleSelectOptions: [ { name: "Backlog", color: GRAY, description: "Holding yard - filed, not yet queued for a train" }, { name: "Todo", color: GREEN, description: "This item hasn't been started" }, { name: "In Progress", color: YELLOW, description: "This is actively being worked on" }, { name: "In Review", color: ORANGE, description: "At an adversarial gate - car done, verdict pending" }, { name: "Done", color: PURPLE, description: "This has been completed" } ] }) { projectV2Field { ... on ProjectV2SingleSelectField { options { id name } } } } }
'@; gh api graphql -f query=$q --jq '.data.updateProjectV2Field.projectV2Field.options'

$q = @'
query { user(login: "polecatspeaks") { projectV2(number: 6) { id items(first: 100) { nodes { id content { ... on Issue { number state } ... on PullRequest { number state } ... on DraftIssue { title } } } } } } }
'@; $r = gh api graphql -f query=$q | ConvertFrom-Json; $proj = $r.data.user.projectV2; "PROJECT: $($proj.id)"; $items = $proj.items.nodes; "ITEMS: $($items.Count)"; $items | Group-Object { $_.content.state } | ForEach-Object { "$($_.Name): $($_.Count)" }

$q = @'
query { user(login: "polecatspeaks") { projectV2(number: 6) { items(first: 100) { nodes { id content { ... on Issue { number state } ... on PullRequest { number state } } } } } } }
'@; $items = (gh api graphql -f query=$q | ConvertFrom-Json).data.user.projectV2.items.nodes; $ok = 0; $fail = 0; foreach ($it in $items) { $opt = if ($it.content.state -eq 'CLOSED') { '2ed477a6' } else { '68d948e1' }; $m = 'mutation { updateProjectV2ItemFieldValue(input: { projectId: "PVT_kwHOAVUqw84BeET6", itemId: "' + $it.id + '", fieldId: "REDACTED", value: { singleSelectOptionId: "' + $opt + '" } }) { projectV2Item { id } } }'; $out = gh api graphql -f query=$m 2>&1; if ($LASTEXITCODE -eq 0) { $ok++ } else { $fail++; "FAIL item $($it.id) issue #$($it.content.number): $out" } }; "restored: $ok ok, $fail failed"

